import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { useLanguage } from '../context/LanguageContext';

const AdminDashboard = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const { t } = useLanguage();
    const [user, setUser] = useState(null);
    const [stats, setStats] = useState({
        totalAppointments: 0,
        pendingAppointments: 0,
        confirmedAppointments: 0,
        totalClients: 0,
        totalServices: 0,
    });
    const [recentAppointments, setRecentAppointments] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check if user is admin
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const userData = JSON.parse(storedUser);
            if (userData.role !== 'admin') {
                navigate('/services');
                return;
            }
            setUser(userData);
        }

        const fetchData = async () => {
            try {
                const token = localStorage.getItem('token');

                // Fetch all appointments
                const appointmentsRes = await axios.get('http://localhost:5000/api/appointments', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                const appointments = appointmentsRes.data.data || [];

                // Calculate stats
                const pending = appointments.filter(a => a.status === 'Pending').length;
                const confirmed = appointments.filter(a => a.status === 'Confirmed').length;

                setStats({
                    totalAppointments: appointments.length,
                    pendingAppointments: pending,
                    confirmedAppointments: confirmed,
                    totalClients: 0,
                    totalServices: 0,
                });

                // Get recent appointments (last 5)
                setRecentAppointments(appointments.slice(0, 5));
            } catch (err) {
                console.error("Error fetching admin data:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [navigate]);

    const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/admin/login'); // Goes to admin login page
};

    const isActive = (path) => location.pathname === path;

    const formatDate = (dateString) => {
        const date = new Date(dateString);
        return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    return (
        <div className="admin-page">
            <nav className="admin-navbar">
                <div className="nav-logo">BeautyBook Admin</div>
                <div className="nav-links-desktop">
                    <span className={`nav-item ${isActive('/admin/dashboard') ? 'active' : ''}`}>
                        📊 Dashboard
                    </span>
                    <span className={`nav-item ${isActive('/admin/appointments') ? 'active' : ''}`} onClick={() => navigate('/admin/appointments')}>
                        📅 Appointments
                    </span>
                    <span className={`nav-item ${isActive('/admin/services') ? 'active' : ''}`} onClick={() => navigate('/admin/services')}>
                        💅 Services
                    </span>
                    <span className={`nav-item ${isActive('/admin/clients') ? 'active' : ''}`} onClick={() => navigate('/admin/clients')}>
                        👤 Clients
                    </span>
                    <span className="nav-icon" onClick={() => navigate('/settings')} style={{cursor: 'pointer'}}>
                        ⚙️
                    </span>
                    <span className="nav-item" onClick={handleLogout} style={{cursor: 'pointer', color: '#d32f2f'}}>
                        🚪 Logout
                    </span>
                </div>
            </nav>

            <div className="admin-content">
                <h1 className="admin-welcome">Welcome back, {user?.firstName || 'Admin'}! 👋</h1>

                {/* Stats Cards */}
                <div className="admin-stats-grid">
                    <div className="stat-card">
                        <div className="stat-icon">📋</div>
                        <div className="stat-info">
                            <h3>{stats.totalAppointments}</h3>
                            <p>Total Appointments</p>
                        </div>
                    </div>
                    <div className="stat-card pending">
                        <div className="stat-icon">⏳</div>
                        <div className="stat-info">
                            <h3>{stats.pendingAppointments}</h3>
                            <p>Pending</p>
                        </div>
                    </div>
                    <div className="stat-card confirmed">
                        <div className="stat-icon">✅</div>
                        <div className="stat-info">
                            <h3>{stats.confirmedAppointments}</h3>
                            <p>Confirmed</p>
                        </div>
                    </div>
                    <div className="stat-card clients">
                        <div className="stat-icon">👥</div>
                        <div className="stat-info">
                            <h3>{stats.totalClients}</h3>
                            <p>Total Clients</p>
                        </div>
                    </div>
                    <div className="stat-card services">
                        <div className="stat-icon">💅</div>
                        <div className="stat-info">
                            <h3>{stats.totalServices}</h3>
                            <p>Services</p>
                        </div>
                    </div>
                </div>

                {/* Recent Appointments */}
                <div className="admin-section">
                    <h2>Recent Appointments</h2>
                    <div className="admin-table-wrapper">
                        {loading ? (
                            <p>Loading appointments...</p>
                        ) : recentAppointments.length === 0 ? (
                            <p>No appointments yet.</p>
                        ) : (
                            <table className="admin-table">
                                <thead>
                                    <tr>
                                        <th>Client</th>
                                        <th>Service</th>
                                        <th>Date</th>
                                        <th>Time</th>
                                        <th>Status</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {recentAppointments.map((app) => (
                                        <tr key={app._id}>
                                            <td>{app.client?.firstName || 'Unknown'}</td>
                                            <td>{app.service?.name || 'Unknown'}</td>
                                            <td>{formatDate(app.appointmentDate)}</td>
                                            <td>{app.startTime} - {app.endTime}</td>
                                            <td>
                                                <span className={`status-badge ${app.status.toLowerCase()}`}>
                                                    {app.status}
                                                </span>
                                            </td>
                                            <td>
                                                {app.status === 'Pending' && (
                                                    <button className="confirm-btn">Confirm</button>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdminDashboard;
